import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * Six parts. `control` is the box — a `role="group"` that carries the accessible
 * name, because the segments inside it are spinbuttons and each one names its own
 * unit. The two triggers are the stepper, out of the tab order and hidden from a reader: the keyboard steps
 * through the segment itself, exactly as `number-input` decided.
 *
 * `hiddenInput` is never `type="date"`. A real date input brings the browser's own
 * calendar UI with it, which is the whole thing this component exists to replace.
 */
export type DateFieldPart =
  | "root"
  | "control"
  | "segment"
  | "incrementTrigger"
  | "decrementTrigger"
  | "hiddenInput";

export const anatomy: Anatomy<DateFieldPart> = createAnatomy("date-field").parts(
  "root",
  "control",
  "segment",
  "incrementTrigger",
  "decrementTrigger",
  "hiddenInput",
);

export const parts: Record<DateFieldPart, AnatomyPart> = anatomy.build();

import { ariaAttr, dataAttr } from "../../dom/attrs";
import { isComposingEvent } from "../../dom/event";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction } from "../../focus/roving-focus";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./date-field.anatomy";
import {
  getControlEl,
  getControlId,
  getHiddenInputId,
  getRootId,
  getSegmentId,
} from "./date-field.dom";
import { toISOValue } from "./date-field.segments";
import type {
  DateFieldApi,
  DateFieldSchema,
  DateFieldValue,
  DateSegment,
  DateSegmentType,
} from "./date-field.types";

export function connect<T extends PropTypes>(
  service: Service<DateFieldSchema>,
  normalize: NormalizeProps<T>,
): DateFieldApi<T> {
  const { context, prop, computed, state, send, scope } = service;

  const value = computed("value");
  const segments = computed("segments");
  const outOfRange = computed("isOutOfRange");
  const editable = computed("isEditable");
  const granularity = prop("granularity");

  const dir = prop("dir");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const required = prop("required");
  // A complete date outside `min`/`max` is invalid, and it is heard as such: that
  // is what a native date input reports through `:out-of-range`. The consumer gets
  // the two apart on `data-out-of-range`.
  const invalid = prop("invalid") === true || outOfRange;

  const engaged = state.matches("engaged");
  const focusedSegment = context.get("focusedSegment");
  // Held from the moment focus landed and only while a segment still has it — the
  // rule every other control in the library follows.
  const focusSource = focusedSegment === null ? null : context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const stateAttrs = {
    "data-disabled": dataAttr(disabled),
    "data-readonly": dataAttr(readOnly),
    "data-invalid": dataAttr(invalid),
    "data-out-of-range": dataAttr(outOfRange),
    "data-engaged": dataAttr(engaged),
  };

  /**
   * The stepper, and its two halves are separate presses, never one state of the
   * field.
   */
  const stepper = (up: boolean): T["button"] =>
    normalize.button({
      ...(up ? parts.incrementTrigger : parts.decrementTrigger).attrs,
      "data-disabled": dataAttr(disabled),
      type: "button",
      disabled: disabled || readOnly,
      // Out of the tab order and out of the accessibility tree: the keyboard steps
      // through the segment itself, so a reader announcing these would offer two
      // ways to do one thing — `number-input`'s reading, and the one the
      // placement of the stepper inside the box implies.
      tabIndex: -1,
      "aria-hidden": "true",
      // And out of the spatial engine too, which does not read either of the two
      // above: `collectNavNodes` filters on this attribute and on empty rects, and
      // `isFocusable` never looks at `aria-hidden` — so a pad reached a button with
      // nothing to announce, which is an `aria-hidden-focus` violation the moment it
      // lands (precedent: `toast.connect.ts:85`, measured again on 2026-09-05).
      "data-snav-ignore": "",
      // A mouse on the stepper must not take the focus out of the segment it is
      // stepping: which segment holds the focus is what decides what a press does.
      onMouseDown(event: MouseEvent) {
        if (!event.defaultPrevented) event.preventDefault();
      },
      onClick(event: MouseEvent) {
        if (event.defaultPrevented) return;
        send({ type: up ? "TRIGGER.INCREMENT" : "TRIGGER.DECREMENT" });
      },
    });

  return {
    value,
    valueAsString: toISOValue(value, granularity),
    segments,
    disabled,
    invalid,
    outOfRange,
    engaged,
    focusedSegment,
    focusSource,
    focusVisible,

    setValue(next: DateFieldValue | null): void {
      send({ type: "VALUE.SET", value: next });
    },
    clear(): void {
      send({ type: "VALUE.CLEAR" });
    },
    increment(): void {
      send({ type: "TRIGGER.INCREMENT" });
    },
    decrement(): void {
      send({ type: "TRIGGER.DECREMENT" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        dir,
        "data-granularity": granularity,
      }),

    /**
     * The group carries the accessible name: the segments inside it are
     * spinbuttons and each already names its own unit, so a name on every segment
     * would read the field's four times over. It also wears the field's control
     * id — `field` sees that a `div` is not labelable, drops its `for`, and the
     * name arrives through `labelledBy` instead. Outside a `field` there is
     * nothing to hand an id down, which is what `label` is for.
     */
    getControlProps: (): T["element"] =>
      normalize.element({
        ...parts.control.attrs,
        ...stateAttrs,
        id: getControlId(scope),
        role: "group",
        "aria-label": prop("label"),
        "aria-labelledby": prop("labelledBy"),
        "aria-describedby": prop("describedBy"),
        "aria-disabled": ariaAttr(disabled),
        "aria-invalid": ariaAttr(invalid),
      }),

    getSegmentProps: (segment: DateSegment): T["element"] => {
      if (segment.type === "literal") {
        return normalize.element({
          ...parts.segment.attrs,
          "data-segment": "literal",
          // No id, no tab stop, no role: a slash is punctuation, and a reader
          // walking the group has nothing to do with it.
          "aria-hidden": "true",
        });
      }

      const type: DateSegmentType = segment.type;
      const focused = focusedSegment === type;

      return normalize.element({
        ...parts.segment.attrs,
        ...stateAttrs,
        id: getSegmentId(scope, type),
        role: "spinbutton",
        // Dropped rather than set to -1: a disabled field is out of the tab order
        // entirely, and a lone `tabindex="-1"` still answers a script's `.focus()`
        // as though it were reachable. Every segment is its own stop — the APG's
        // arrangement for spinbuttons, and why there is no roving here.
        tabIndex: disabled ? undefined : 0,
        "data-segment": type,
        "data-placeholder": dataAttr(segment.isPlaceholder),
        "data-engaged": dataAttr(engaged && focused),
        "data-focus-visible": dataAttr(focused && focusVisible),
        "data-focus-source": focused ? (focusSource ?? undefined) : undefined,
        "aria-label": segment.label,
        "aria-valuemin": segment.min,
        "aria-valuemax": segment.max,
        // Omitted while the segment is empty, which is what the APG asks of a
        // spinbutton with no value: there is no number to announce yet.
        "aria-valuenow": segment.value ?? undefined,
        // Only when the text adds something, and the question is asked of the
        // *number* the text reads as, not of its spelling: a compare on strings
        // called `"04"` a different value from `4` and emitted `valuetext="04"`
        // beside `valuenow="4"` on every padded unit — the double announcement
        // this guard exists to prevent. `Number` is `NaN` on a word, so the day
        // period, which is the case that genuinely reads otherwise, still speaks.
        "aria-valuetext":
          segment.value !== null && Number(segment.text) !== segment.value
            ? segment.text
            : undefined,
        "aria-disabled": ariaAttr(disabled),
        "aria-readonly": ariaAttr(readOnly),
        "aria-required": ariaAttr(required),
        // On the segment as well as on the group, because the segment is the
        // `role="spinbutton"` — the element that owns the value, which is where
        // `slider` puts it for the same reason (slider.connect.ts:191-194) and
        // where `radio-group` puts it on both the group and every item
        // (radio-group.connect.ts:75 and :137). Nothing ever focuses the group,
        // so a field marked invalid announced nothing at all when entered
        // segment-first. The description stays on the group alone: it is one
        // sentence about the field, and six segments would each repeat it.
        "aria-invalid": ariaAttr(invalid),
        onKeyDown(event: KeyboardEvent) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          if (isComposingEvent(event)) return;
          const key = event.key;

          if (key.length === 1 && key >= "0" && key <= "9") {
            event.preventDefault();
            send({ type: "SEGMENT.INPUT", segment: type, digit: Number(key) });
            return;
          }

          if (key === "Backspace" || key === "Delete") {
            event.preventDefault();
            send({ type: "SEGMENT.CLEAR", segment: type });
            return;
          }

          if (key === "ArrowUp" || key === "ArrowDown" || key === "PageUp" || key === "PageDown") {
            // The editable test sits before `preventDefault`, deliberately: on a
            // read-only field PageDown still belongs to the page.
            if (!editable) return;
            event.preventDefault();
            const up = key === "ArrowUp" || key === "PageUp";
            send({
              type: up ? "SEGMENT.INCREMENT" : "SEGMENT.DECREMENT",
              segment: type,
              large: key === "PageUp" || key === "PageDown",
            });
            return;
          }

          // Resolved here and not at the top of `connect`: with no `dir` prop the
          // answer is read off the control, and a DOM read during render would run
          // on the server.
          const action = getRovingKeyAction(key, {
            orientation: "horizontal",
            dir: resolveDir(dir, getControlEl(scope)),
          });
          if (action === null) return;
          event.preventDefault();
          send({ type: "SEGMENT.MOVE", action });
        },
        onFocus(event: FocusEvent) {
          if (!event.defaultPrevented) send({ type: "SEGMENT.FOCUS", segment: type });
        },
        onBlur(event: FocusEvent) {
          if (!event.defaultPrevented) send({ type: "SEGMENT.BLUR" });
        },
      });
    },

    getIncrementTriggerProps: (): T["button"] => stepper(true),
    getDecrementTriggerProps: (): T["button"] => stepper(false),

    /**
     * `type="hidden"`, never `type="date"`: a real date input brings the browser's
     * own picker with it — the very thing this component replaces — and puts a
     * second date control in the accessibility tree beside the group.
     */
    getHiddenInputProps: (): T["input"] =>
      normalize.input({
        ...parts.hiddenInput.attrs,
        id: getHiddenInputId(scope),
        type: "hidden",
        name: prop("name"),
        form: prop("form"),
        // Native rule: a disabled control is not submitted.
        disabled,
        value: toISOValue(value, granularity),
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";
import type { DateSegmentType } from "./date-field.types";

/**
 * Only the parts something points at get an id: the root, the group a field names,
 * one per segment because the machine moves the real focus between them, and the
 * hidden input because the form reset listener has to find the form through it.
 */
const COMPONENT = "date-field";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getControlId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "control");
}

export function getSegmentId(scope: Scope, segment: DateSegmentType): string {
  return getPartId(scope, COMPONENT, "segment", segment);
}

export function getHiddenInputId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "hiddenInput");
}

export function getControlEl(scope: Scope): HTMLElement | null {
  return scope.getById(getControlId(scope));
}

export function getSegmentEl(scope: Scope, segment: DateSegmentType): HTMLElement | null {
  return scope.getById(getSegmentId(scope, segment));
}

export function getHiddenInputEl(scope: Scope): HTMLInputElement | null {
  return scope.getById<HTMLInputElement>(getHiddenInputId(scope));
}

/**
 * A date typed unit by unit: one `role="spinbutton"` per year, month and day, plus
 * — past `granularity: "day"` — an hour, a minute, a second and a day period.
 * `time-field` is this machine at a finer granularity and not a second component
 * behind it, which is CDC D10 in the small: the same reading that made
 * `password-input` a presentation of `input`.
 *
 * **One piece of state, and it is not the value.** `parts` holds a number per unit
 * or `null`, because a half-typed date is a state a user can really be in and a
 * `DateValue` is not — there is no `{ year: 2026, month: null }`. The value is
 * *composed* from the parts and reported only once every unit the granularity asks
 * for is filled, so the bindable carrying the controlled/uncontrolled contract is
 * the parts record itself and there is nothing to keep in step with anything.
 *
 * **Three states, and each one owns an effect to unmount.** `focused` holds the
 * scope A is claimed on and `engaged` holds the one that turns a direction into an
 * adjustment (CDC §4.4). The spec asked for two; a field inside a dialog is what
 * settled it, because the scope has to be pushed when focus lands rather than at
 * mount — mount is too early, and the surface's own scope would sit above it.
 *
 * **The type-ahead buffer keeps no timer.** A digit records when it landed and the
 * next one asks how long ago that was. A `setTimeout` here would be an effect per
 * keystroke and a cleanup to get wrong, for a deadline nothing rendered can see.
 *
 * **`min`/`max` bound the arrows, never the digits.** A range check on typing
 * would refuse the keystroke that completes a date from the wrong end — type the
 * year last under `min: 2026-01-01` and 2 is out of range before 2026 exists. A
 * complete value outside the range is reported instead, on `isOutOfRange`, which
 * is what `input[type=date]` does with `:out-of-range`.
 */

import { addDomEvent } from "../../dom/event";
import { resolveDir } from "../../dom/text-dir";
import { getNextIndex, type RovingAction } from "../../focus/roving-focus";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement, getInputModality, pushEngageScope, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getToday } from "../../utils/date-format";
import { getControlEl, getHiddenInputEl, getSegmentEl } from "./date-field.dom";
import {
  adjustSegment,
  buildSegments,
  composeDateValue,
  EMPTY_SEGMENT_VALUES,
  editableSegments,
  isWithinRange,
  type SegmentContext,
  segmentValuesEqual,
  TYPE_BUFFER_MS,
  toSegmentValues,
  typeDigit,
  withoutSegment,
} from "./date-field.segments";
import type {
  DateFieldSchema,
  DateFieldValue,
  DateSegmentType,
  DateSegmentValues,
} from "./date-field.types";

type Params = MachineParams<DateFieldSchema>;

/** PageUp/PageDown, the spinbutton's large step. */
const LARGE_STEP = 10;

function layout(params: Params): SegmentContext {
  return {
    locale: params.prop("locale"),
    granularity: params.prop("granularity"),
    hourCycle: params.prop("hourCycle"),
  };
}

/**
 * Where an arrow starts from on an empty segment, and the one place a clock is
 * read. It is called from `adjustSegment` alone — never from a computed value —
 * so a server that has a different day than the client cannot put its own date
 * into an attribute the client then has to disagree with.
 */
function placeholderOf(params: Params): DateFieldValue {
  const declared = params.prop("placeholder");
  if (declared !== undefined) return declared;
  let today = params.refs.get("today");
  if (today === null) {
    today = getToday();
    params.refs.set("today", today);
  }
  return today;
}

function order(params: Params): DateSegmentType[] {
  return editableSegments(params.computed("segments"));
}

/**
 * Moves the real focus, and it has to come last in any action list: focusing an
 * element fires `focus` synchronously, the segment answers with `SEGMENT.FOCUS`,
 * and that re-entrant delivery replaces the event the actions still to run are
 * reading — the ordering `slider`'s `focusThumb` pays for too.
 */
function focusSegment(params: Params, segment: DateSegmentType): void {
  params.context.set("focusedSegment", segment);
  params.context.set("typeBuffer", "");
  // The blur this fires is not the user leaving: it is the machine walking to the
  // next unit, and an engaged field that treated it as a departure would drop the
  // hold every time a d-pad moved sideways.
  params.refs.set("movingFocus", true);
  focusElement(getSegmentEl(params.scope, segment));
  params.refs.set("movingFocus", false);
}

/** The next segment along, or nothing when the field ends there. Tab is what leaves. */
function neighbour(
  types: readonly DateSegmentType[],
  from: DateSegmentType,
): DateSegmentType | null {
  const index = types.indexOf(from);
  if (index < 0) return null;
  return types[index + 1] ?? null;
}

function adjustBy(params: Params, segment: DateSegmentType, delta: number): void {
  const { context, prop } = params;
  const next = adjustSegment(
    context.get("parts"),
    segment,
    delta,
    prop("hourCycle"),
    placeholderOf(params),
  );
  // The bounds are read after the whole date is recomposed, not unit by unit:
  // stepping a month is legal or not because of the date it lands on.
  if (!isWithinRange(composeDateValue(next, prop("granularity")), prop("min"), prop("max"))) return;
  context.set("parts", next);
}

/** The segment an `aria-hidden` stepper acts on: the focused one, or the first. */
function targetSegment(params: Params): DateSegmentType | null {
  return params.context.get("focusedSegment") ?? order(params)[0] ?? null;
}

/**
 * `moveLeft`/`moveRight` are physical — a d-pad has no writing direction — so the
 * mirror happens here, once, exactly where `getRovingKeyAction` does it for the
 * keyboard.
 */
function toRovingAction(
  intent: "moveLeft" | "moveRight" | "home" | "end",
  params: Params,
): RovingAction {
  if (intent === "home") return "first";
  if (intent === "end") return "last";
  const rtl = resolveDir(params.prop("dir"), getControlEl(params.scope)) === "rtl";
  return (intent === "moveRight") === rtl ? "prev" : "next";
}

export const machine: Machine<DateFieldSchema> = createMachine<DateFieldSchema>({
  props({ props }) {
    return {
      granularity: "day",
      hourCycle: "h12",
      // Pinned, for the same reason `slider` and `progress` pin theirs — and with
      // more at stake: this one decides the *order* of the children, so a locale
      // read from the browser would have the server and the client render
      // different markup, not merely a different string.
      locale: "en-US",
      disabled: false,
      invalid: false,
      readOnly: false,
      required: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      parts: bindable<DateSegmentValues>(() => ({
        defaultValue: toSegmentValues(prop("defaultValue")),
        // Passed through rather than normalised on every read: a controlled value
        // belongs to the consumer, and the segments clamp what they draw.
        value: prop("value") === undefined ? undefined : toSegmentValues(prop("value")),
        // Without this, every write of a fresh record — which is every write —
        // would report a change and re-render, forever.
        isEqual: segmentValuesEqual,
        onChange: (parts) =>
          prop("onValueChange")?.({ value: composeDateValue(parts, prop("granularity")) }),
        debugLabel: "date-field value",
      })),
      focusedSegment: bindable<DateSegmentType | null>(() => ({ defaultValue: null })),
      typeBuffer: bindable<string>(() => ({ defaultValue: "" })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  computed: {
    value: ({ context, prop }) => composeDateValue(context.get("parts"), prop("granularity")),
    segments: (params) => buildSegments(params.context.get("parts"), layout(params)),
    isEditable: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    /**
     * Never while a unit is half typed. Typing is not range-checked — every prefix
     * of 2026 is a year outside a 2026 minimum, and a field that refused them
     * could not be filled in at all — but *announcing* it is another matter: the
     * first three digits of a four-digit year each flipped the field to invalid,
     * and since `aria-invalid` reached the segment (2026-09-06) a reader heard it
     * on every keystroke. A non-empty `typeBuffer` is exactly "this unit is not
     * finished", so the range is asked once it is.
     */
    isOutOfRange: ({ context, prop }) =>
      context.get("typeBuffer") === "" &&
      !isWithinRange(
        composeDateValue(context.get("parts"), prop("granularity")),
        prop("min"),
        prop("max"),
      ),
  },

  refs() {
    return { entryParts: null, lastDigitAt: 0, movingFocus: false, today: null };
  },

  // Pure: no DOM, no clock, no environment. The server renders what the client
  // hydrates, down to the order of the segments.
  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackFormReset"],

  watch({ prop, track, action }) {
    // Only a granularity that *grew* has anything to do here, and the action
    // answers for that: the other direction needs nothing, because the value is
    // composed from the parts and a coarser granularity simply stops asking for
    // the ones it does not want (`composeDateValue`).
    track(
      () => [prop("granularity")],
      () => action(["fillFromPlaceholder"]),
    );
  },

  on: {
    "VALUE.SET": { guard: "isEditable", actions: ["setValue"] },
    "VALUE.CLEAR": { guard: "isEditable", actions: ["clearValue"] },
    "SEGMENT.FOCUS": { target: "focused", actions: ["setFocusedSegment", "captureFocusSource"] },
    "SEGMENT.BLUR": { target: "idle", actions: ["clearFocusedSegment", "clearFocusSource"] },
    "SEGMENT.MOVE": { actions: ["moveSegment"] },
    "SEGMENT.INPUT": { guard: "isEditable", actions: ["appendDigit"] },
    "SEGMENT.INCREMENT": { guard: "isEditable", actions: ["adjustSegment"] },
    "SEGMENT.DECREMENT": { guard: "isEditable", actions: ["adjustSegment"] },
    "SEGMENT.CLEAR": { guard: "isEditable", actions: ["clearSegment"] },
    "TRIGGER.INCREMENT": { guard: "isEditable", actions: ["adjustFocusedSegment"] },
    "TRIGGER.DECREMENT": { guard: "isEditable", actions: ["adjustFocusedSegment"] },
    "FORM.RESET": { actions: ["restoreInitialValue"] },
  },

  states: {
    idle: {},

    /**
     * The scope A pushes lives here and not at machine level, and the reason is
     * the stack: a field inside a dialog mounts before the dialog's own effects
     * install, so a scope pushed at mount would sit *under* the surface's and
     * never see the button. Pushed when focus lands, it is on top of whatever
     * opened around it — the arrangement `slider.focused` already pays for.
     */
    focused: {
      effects: ["captureSelectIntent"],
      on: { "ENGAGE.START": { guard: "canEngage", target: "engaged" } },
    },

    /**
     * The snapshot is taken on entry and read on the way out, and deliberately not
     * cleared on exit: the interpreter runs a state's exit actions before the
     * transition's own, so an exit that cleared it would erase the value B is
     * there to restore. Entry overwrites it, which is the same guarantee one step
     * later — the arrangement `slider.engaged` already carries.
     */
    engaged: {
      entry: ["snapshotParts"],
      effects: ["captureEngageIntents"],
      on: {
        "ENGAGE.END": [
          {
            guard: ({ event }) => event.type === "ENGAGE.END" && event.committed,
            target: "focused",
            actions: ["clearSnapshot"],
          },
          { target: "focused", actions: ["restoreParts"] },
        ],
        // A blur the machine ordered itself is a step sideways, not a departure;
        // any other one is the user leaving, and the hold ends with it — the
        // effect's own dispose pops the scope without reporting a release, which
        // is what unmounting means as opposed to letting go.
        "SEGMENT.BLUR": [
          { guard: "isMovingFocus" },
          { target: "idle", actions: ["clearFocusedSegment", "clearFocusSource"] },
        ],
        "SEGMENT.FOCUS": { actions: ["setFocusedSegment"] },
      },
    },
  },

  implementations: {
    guards: {
      isEditable: ({ prop }) => !prop("disabled") && !prop("readOnly"),
      canEngage: ({ prop, context }) =>
        !prop("disabled") &&
        !prop("readOnly") &&
        prop("intents") !== null &&
        context.get("focusedSegment") !== null,
      isMovingFocus: ({ refs }) => refs.get("movingFocus"),
    },

    actions: {
      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("parts", toSegmentValues(event.value));
      },

      clearValue({ context }) {
        context.set("parts", EMPTY_SEGMENT_VALUES);
        context.set("typeBuffer", "");
      },

      setFocusedSegment({ context, event }) {
        if (event.type !== "SEGMENT.FOCUS") return;
        context.set("focusedSegment", event.segment);
        context.set("typeBuffer", "");
      },

      clearFocusedSegment({ context }) {
        context.set("focusedSegment", null);
        context.set("typeBuffer", "");
      },

      moveSegment(params) {
        const { event, context } = params;
        if (event.type !== "SEGMENT.MOVE") return;
        const types = order(params);
        if (types.length === 0) return;
        const current = context.get("focusedSegment");
        const index = current === null ? -1 : types.indexOf(current);
        // No wrap: a segmented field ends where it ends, and Tab is what leaves
        // it — an arrow that looped would take the year back to the month and
        // never reach whatever comes after the control.
        const next = types[getNextIndex(index, event.action, { count: types.length, loop: false })];
        if (next !== undefined) focusSegment(params, next);
      },

      adjustSegment(params) {
        const { event } = params;
        if (event.type !== "SEGMENT.INCREMENT" && event.type !== "SEGMENT.DECREMENT") return;
        const magnitude = event.large ? LARGE_STEP : 1;
        adjustBy(
          params,
          event.segment,
          event.type === "SEGMENT.INCREMENT" ? magnitude : -magnitude,
        );
      },

      adjustFocusedSegment(params) {
        const { event } = params;
        if (event.type !== "TRIGGER.INCREMENT" && event.type !== "TRIGGER.DECREMENT") return;
        const segment = targetSegment(params);
        if (segment === null) return;
        adjustBy(params, segment, event.type === "TRIGGER.INCREMENT" ? 1 : -1);
      },

      /**
       * The two-digit buffer and the auto-advance it owes. `12` in a month fills
       * it and moves on, because no third digit could fit; `1` then `3` keeps
       * January and opens the next segment with the 3, because 13 is not a month
       * and swallowing the keystroke would leave a user typing into a segment
       * that will never take it.
       */
      appendDigit(params) {
        const { context, prop, refs, event } = params;
        if (event.type !== "SEGMENT.INPUT") return;
        const now = Date.now();
        const stale = now - refs.get("lastDigitAt") > TYPE_BUFFER_MS;
        const buffer =
          stale || context.get("focusedSegment") !== event.segment ? "" : context.get("typeBuffer");
        const parts = context.get("parts");
        const hourCycle = prop("hourCycle");

        const typed = typeDigit(parts, event.segment, event.digit, buffer, hourCycle);
        if (typed !== null) {
          refs.set("lastDigitAt", now);
          context.set("parts", typed.parts);
          // Emptied the moment the unit is complete, and not only when there is a
          // next segment to move to: the buffer is what says "a unit is half
          // typed", and the last segment of the order had no way of ever saying it
          // was finished. `isOutOfRange` reads it — see the computed.
          context.set("typeBuffer", typed.complete ? "" : typed.buffer);
          if (!typed.complete) return;
          const after = neighbour(order(params), event.segment);
          if (after !== null) focusSegment(params, after);
          return;
        }

        const next = neighbour(order(params), event.segment);
        if (next === null) return;
        const restarted = typeDigit(parts, next, event.digit, "", hourCycle);
        if (restarted === null) return;
        refs.set("lastDigitAt", now);
        context.set("parts", restarted.parts);
        const after = restarted.complete ? neighbour(order(params), next) : null;
        focusSegment(params, after ?? next);
        if (after === null) context.set("typeBuffer", restarted.buffer);
      },

      clearSegment(params) {
        const { context, event } = params;
        if (event.type !== "SEGMENT.CLEAR") return;
        context.set("parts", withoutSegment(context.get("parts"), event.segment));
        context.set("typeBuffer", "");
      },

      captureFocusSource({ context, scope }) {
        // A segment can be focused without a document in reach — a machine test
        // sends the event, and `getDoc` throws rather than invent one.
        if (scope.getRootNode() === null) return;
        context.set("focusSource", getInputModality(scope.getDoc()));
      },

      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },

      /**
       * A granularity switched up mid-session asks for units the field never
       * had, and the declared placeholder is where they come from — never the
       * clock `placeholderOf` falls back to. Filling from today would put a time
       * nobody chose into a form, and a server's hour into markup a client would
       * disagree with; with no `placeholder` prop the new segments stay dashes,
       * which is the spec's own second clause.
       *
       * Nothing above the granularity is written either: a `second` copied into
       * an `hour` field would sit there unseen and surface the day the field
       * grew again, which is inventing a value one step late.
       */
      fillFromPlaceholder({ context, prop }) {
        const from = prop("placeholder");
        const granularity = prop("granularity");
        if (from === undefined || granularity === "day") return;
        const parts = context.get("parts");
        context.set("parts", {
          ...parts,
          hour: parts.hour ?? from.hour ?? null,
          minute: granularity === "hour" ? parts.minute : (parts.minute ?? from.minute ?? null),
          second: granularity === "second" ? (parts.second ?? from.second ?? null) : parts.second,
        });
      },

      snapshotParts({ context, refs }) {
        refs.set("entryParts", context.get("parts"));
      },

      restoreParts({ context, refs }) {
        const entry = refs.get("entryParts");
        if (entry !== null) context.set("parts", entry);
      },

      clearSnapshot({ refs }) {
        refs.set("entryParts", null);
      },

      restoreInitialValue({ context }) {
        context.set("parts", context.initial("parts"));
        context.set("typeBuffer", "");
      },
    },

    effects: {
      // No listener of its own: the source is read once, when focus lands. Holding
      // the handle is the whole job — the tracker has to be running before the
      // first Tab.
      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      /**
       * A `type="hidden"` input carries no default the browser will restore — the
       * adapter owns its value — so the form's own `reset` is what puts the field
       * back where it started. In capture, so a listener that cancels the reset
       * further down cannot silently take the field out of it.
       */
      trackFormReset({ scope, send }) {
        return addDomEvent(
          getHiddenInputEl(scope)?.form,
          "reset",
          () => send({ type: "FORM.RESET" }),
          { capture: true },
        );
      },

      /**
       * A is how a pad takes hold, claimed while a segment is focused and nowhere
       * else, so the scope is on the stack for exactly as long as the grab is
       * possible. Never from a keyboard: Enter in a field belongs to the form
       * around it, and a keyboard engage would hand Escape the power to rewind a
       * date the user had settled on.
       */
      captureSelectIntent({ prop, context, send }) {
        const host = prop("intents");
        if (host === null) return;
        return host.pushScope((event) => {
          if (event.intent !== "select" || event.source === "keyboard") return false;
          if (prop("disabled") || prop("readOnly")) return false;
          if (context.get("focusedSegment") === null) return false;
          send({ type: "ENGAGE.START" });
          return true;
        });
      },

      /**
       * The pad's hold on the value: up and down adjust, left and right walk the
       * segments, A commits and B puts back the value the hold started on.
       * `pushEngageScope` consumes `back`, so B releases the segment instead of
       * popping the layer underneath — a date field inside a popover must not
       * close the popover on the way out.
       */
      captureEngageIntents(params) {
        const { prop, context, send } = params;
        const host = prop("intents");
        if (host === null) return;
        return pushEngageScope(host, {
          onAdjust: (intent) => {
            const segment = context.get("focusedSegment");
            if (segment === null) return;
            if (intent === "moveUp" || intent === "pageUp") {
              send({ type: "SEGMENT.INCREMENT", segment, large: intent === "pageUp" });
              return;
            }
            if (intent === "moveDown" || intent === "pageDown") {
              send({ type: "SEGMENT.DECREMENT", segment, large: intent === "pageDown" });
              return;
            }
            send({ type: "SEGMENT.MOVE", action: toRovingAction(intent, params) });
          },
          onRelease: (committed) => send({ type: "ENGAGE.END", committed }),
        });
      },
    },
  },
});

/**
 * The segment arithmetic: what a locale's `formatToParts` lays out, what each unit
 * is allowed to hold, and how a digit, an arrow or a stepper turns one number into
 * the next. Pure — no DOM, no service, no `Date` in a value.
 *
 * It lives in the component and not in `utils/date-format` because that module and
 * `plain-date` both carry a civil *date*, and a field at `granularity: "minute"`
 * carries a time as well. Three of the helpers below are general enough that
 * `calendar` and `date-picker` will want them — `toUTCDateTime`, `getUnitLabel`
 * and `toISOValue` — and they are named in the hand-off so they can move up once
 * those two have landed and the shared module has one owner again.
 *
 * **The day period is derived, never stored.** The hour is held once, on the
 * 24-hour clock, and `h12` reads a segment pair out of it. Storing both would let
 * "13" and "PM" disagree, and no state would say which one is right.
 *
 * **Nothing rendered here reads a clock.** Unfilled units resolve to fixed
 * constants — a leap year and January, the pair that can hold any day a user is
 * entitled to type — so a server in UTC and a client thirteen hours ahead emit the
 * same `aria-valuemax` and the same dashes. A placeholder date, which may well be
 * today, is consulted in exactly one function: `adjustSegment`, where an arrow
 * steps an empty segment, and that only ever runs after a keypress on a client.
 */

import { getDateFormatter } from "../../utils/date-format";
import {
  compareDates,
  type DateValue,
  daysInMonth,
  fromParts,
  MAX_DATE_YEAR,
  MIN_DATE_YEAR,
  toISO,
  toUTCDate,
} from "../../utils/plain-date";
import type {
  DateFieldValue,
  DateGranularity,
  DateHourCycle,
  DateSegment,
  DateSegmentType,
  DateSegmentUnit,
  DateSegmentValues,
} from "./date-field.types";

/** Everything the layout of the field depends on, and nothing else. */
export interface SegmentContext {
  readonly locale: string;
  readonly granularity: DateGranularity;
  readonly hourCycle: DateHourCycle;
}

/** Every unit filled in — what the formatter is handed and what bounds read from. */
export interface ResolvedDateTime {
  readonly year: number;
  readonly month: number;
  readonly day: number;
  readonly hour: number;
  readonly minute: number;
  readonly second: number;
}

export interface SegmentBounds {
  readonly min: number;
  readonly max: number;
}

/** What a digit did to a segment, and whether the segment can hold another one. */
export interface DigitResult {
  readonly parts: DateSegmentValues;
  readonly buffer: string;
  /** No further digit could fit, so the focus moves on by itself. */
  readonly complete: boolean;
}

export const EMPTY_SEGMENT_VALUES: DateSegmentValues = {
  year: null,
  month: null,
  day: null,
  hour: null,
  minute: null,
  second: null,
};

/** Long enough to finish typing "2026", short enough that a pause starts over. */
export const TYPE_BUFFER_MS = 1000;

/** A leap year, so an unknown year never refuses the 29th of February. */
const SHAPE_YEAR = 2024;
/** January, so an unknown month holds any day from the 1st to the 31st. */
const SHAPE_MONTH = 1;

const SEGMENT_TYPES: ReadonlySet<string> = new Set<DateSegmentType>([
  "year",
  "month",
  "day",
  "hour",
  "minute",
  "second",
  "dayPeriod",
]);

const DATE_OPTIONS: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
};

const unitLabels = new Map<string, string>();

function formatOptionsFor(
  granularity: DateGranularity,
  hourCycle: DateHourCycle,
): Intl.DateTimeFormatOptions {
  if (granularity === "day") return DATE_OPTIONS;
  const withHour: Intl.DateTimeFormatOptions = { ...DATE_OPTIONS, hour: "2-digit", hourCycle };
  if (granularity === "hour") return withHour;
  const withMinute: Intl.DateTimeFormatOptions = { ...withHour, minute: "2-digit" };
  if (granularity === "minute") return withMinute;
  return { ...withMinute, second: "2-digit" };
}

function asSegmentType(type: string): DateSegmentType | null {
  return SEGMENT_TYPES.has(type) ? (type as DateSegmentType) : null;
}

/** The unit a segment reads and writes: the day period is the hour, seen twelve-wise. */
function unitOf(type: DateSegmentType): DateSegmentUnit {
  return type === "dayPeriod" ? "hour" : type;
}

export function isSegmentFilled(parts: DateSegmentValues, type: DateSegmentType): boolean {
  return parts[unitOf(type)] !== null;
}

export function toSegmentValues(value: DateFieldValue | null | undefined): DateSegmentValues {
  if (value === null || value === undefined) return EMPTY_SEGMENT_VALUES;
  return {
    year: value.year,
    month: value.month,
    day: value.day,
    hour: value.hour ?? null,
    minute: value.minute ?? null,
    second: value.second ?? null,
  };
}

export function segmentValuesEqual(a: DateSegmentValues, b: DateSegmentValues): boolean {
  return (
    a.year === b.year &&
    a.month === b.month &&
    a.day === b.day &&
    a.hour === b.hour &&
    a.minute === b.minute &&
    a.second === b.second
  );
}

/** The rendered shape: what has been typed, and constants for what has not. */
export function resolveShape(parts: DateSegmentValues): ResolvedDateTime {
  const year = parts.year ?? SHAPE_YEAR;
  const month = parts.month ?? SHAPE_MONTH;
  return {
    year,
    month,
    day: Math.min(parts.day ?? 1, daysInMonth(year, month)),
    hour: parts.hour ?? 0,
    minute: parts.minute ?? 0,
    second: parts.second ?? 0,
  };
}

/** The stepping shape: a placeholder fills what has not been typed. */
export function resolveFromPlaceholder(
  parts: DateSegmentValues,
  placeholder: DateFieldValue,
): ResolvedDateTime {
  const year = parts.year ?? placeholder.year;
  const month = parts.month ?? placeholder.month;
  return {
    year,
    month,
    day: Math.min(parts.day ?? placeholder.day, daysInMonth(year, month)),
    hour: parts.hour ?? placeholder.hour ?? 0,
    minute: parts.minute ?? placeholder.minute ?? 0,
    second: parts.second ?? placeholder.second ?? 0,
  };
}

/** Midnight-plus-a-time UTC: `plain-date` builds the day, this adds the clock. */
export function toUTCDateTime(value: DateFieldValue): Date {
  const date = toUTCDate(value);
  date.setUTCHours(value.hour ?? 0, value.minute ?? 0, value.second ?? 0, 0);
  return date;
}

/**
 * The value, or `null` while any unit the granularity asks for is still empty. A
 * half-typed date is not a date, and reporting one would have a form submit the
 * 1st of a month nobody chose.
 */
export function composeDateValue(
  parts: DateSegmentValues,
  granularity: DateGranularity,
): DateFieldValue | null {
  const { year, month, day, hour, minute, second } = parts;
  if (year === null || month === null || day === null) return null;
  const date = fromParts(year, month, day);
  if (granularity === "day") return date;
  if (hour === null) return null;
  if (granularity === "hour") return { ...date, hour };
  if (minute === null) return null;
  if (granularity === "minute") return { ...date, hour, minute };
  if (second === null) return null;
  return { ...date, hour, minute, second };
}

export function isWithinRange(
  value: DateFieldValue | null,
  min: DateValue | undefined,
  max: DateValue | undefined,
): boolean {
  if (value === null) return true;
  if (min !== undefined && compareDates(value, min) < 0) return false;
  return max === undefined || compareDates(value, max) <= 0;
}

/** What a form receives: `datetime-local`'s own spelling past `granularity: "day"`. */
export function toISOValue(value: DateFieldValue | null, granularity: DateGranularity): string {
  if (value === null) return "";
  const date = toISO(value);
  if (granularity === "day") return date;
  const pad = (input: number): string => String(input).padStart(2, "0");
  const time = `${pad(value.hour ?? 0)}:${pad(value.minute ?? 0)}`;
  return granularity === "second" ? `${date}T${time}:${pad(value.second ?? 0)}` : `${date}T${time}`;
}

export function getSegmentBounds(
  type: DateSegmentType,
  resolved: ResolvedDateTime,
  hourCycle: DateHourCycle,
): SegmentBounds {
  switch (type) {
    case "year":
      return { min: MIN_DATE_YEAR, max: MAX_DATE_YEAR };
    case "month":
      return { min: 1, max: 12 };
    case "day":
      return { min: 1, max: daysInMonth(resolved.year, resolved.month) };
    case "hour":
      return hourCycle === "h12" ? { min: 1, max: 12 } : { min: 0, max: 23 };
    case "dayPeriod":
      return { min: 0, max: 1 };
    default:
      return { min: 0, max: 59 };
  }
}

/** The number the segment shows — the hour twelve-wise, the period as 0 or 1. */
export function getSegmentDisplay(
  type: DateSegmentType,
  resolved: ResolvedDateTime,
  hourCycle: DateHourCycle,
): number {
  switch (type) {
    case "year":
      return resolved.year;
    case "month":
      return resolved.month;
    case "day":
      return resolved.day;
    case "hour":
      return hourCycle === "h12" ? resolved.hour % 12 || 12 : resolved.hour;
    case "minute":
      return resolved.minute;
    case "second":
      return resolved.second;
    default:
      return resolved.hour >= 12 ? 1 : 0;
  }
}

export function withSegment(
  parts: DateSegmentValues,
  type: DateSegmentType,
  next: number,
  hourCycle: DateHourCycle,
): DateSegmentValues {
  if (type === "dayPeriod") {
    const hour = (parts.hour ?? 0) % 12;
    return { ...parts, hour: next === 1 ? hour + 12 : hour };
  }
  if (type === "hour" && hourCycle === "h12") {
    const afternoon = (parts.hour ?? 0) >= 12;
    const base = next % 12;
    return { ...parts, hour: afternoon ? base + 12 : base };
  }
  const merged: DateSegmentValues = {
    year: type === "year" ? next : parts.year,
    month: type === "month" ? next : parts.month,
    day: type === "day" ? next : parts.day,
    hour: type === "hour" ? next : parts.hour,
    minute: type === "minute" ? next : parts.minute,
    second: type === "second" ? next : parts.second,
  };
  // A month or a year that shortens the month takes the day with it: the 31st of
  // March moved into February is the 28th, never a day that does not exist.
  if (merged.year !== null && merged.month !== null && merged.day !== null) {
    const last = daysInMonth(merged.year, merged.month);
    if (merged.day > last) return { ...merged, day: last };
  }
  return merged;
}

export function withoutSegment(parts: DateSegmentValues, type: DateSegmentType): DateSegmentValues {
  const unit = unitOf(type);
  return {
    year: unit === "year" ? null : parts.year,
    month: unit === "month" ? null : parts.month,
    day: unit === "day" ? null : parts.day,
    hour: unit === "hour" ? null : parts.hour,
    minute: unit === "minute" ? null : parts.minute,
    second: unit === "second" ? null : parts.second,
  };
}

export function adjustSegment(
  parts: DateSegmentValues,
  type: DateSegmentType,
  delta: number,
  hourCycle: DateHourCycle,
  placeholder: DateFieldValue,
): DateSegmentValues {
  const shape = resolveShape(parts);
  const { min, max } = getSegmentBounds(type, shape, hourCycle);
  // An empty segment lands on the placeholder rather than wrapping in from
  // nowhere: an arrow on a blank month means "this month", not January.
  if (!isSegmentFilled(parts, type)) {
    const start = getSegmentDisplay(type, resolveFromPlaceholder(parts, placeholder), hourCycle);
    return withSegment(parts, type, Math.min(Math.max(start, min), max), hourCycle);
  }
  const shown = getSegmentDisplay(type, shape, hourCycle);
  const span = max - min + 1;
  return withSegment(
    parts,
    type,
    min + ((((shown + delta - min) % span) + span) % span),
    hourCycle,
  );
}

/**
 * One digit into a segment, or `null` when the buffer cannot take it.
 *
 * `null` is not a refusal to type — it is the auto-advance: a month holding 1 that
 * is handed a 3 keeps January, and the 3 opens the next segment. That is what a
 * two-digit buffer owes, and it is why the caller decides what happens next
 * instead of this function inventing a month of 13.
 */
export function typeDigit(
  parts: DateSegmentValues,
  type: DateSegmentType,
  digit: number,
  buffer: string,
  hourCycle: DateHourCycle,
): DigitResult | null {
  // The period is a word, not a number. It has two values and the arrows reach
  // both, which is the whole of what a two-valued spinbutton owes.
  if (type === "dayPeriod") return null;
  const { min, max } = getSegmentBounds(type, resolveShape(parts), hourCycle);
  const next = buffer === "" ? digit : Number(`${buffer}${digit}`);
  if (next > max) return null;
  return {
    // Below the minimum is a prefix, not a value: the `0` of "09" on a 12-hour
    // clock is a segment the next digit is about to complete.
    parts: next < min ? parts : withSegment(parts, type, next, hourCycle),
    buffer: `${buffer}${digit}`,
    complete: next * 10 > max,
  };
}

/**
 * The unit's name in the field's own locale. `Intl.DisplayNames` already carries
 * this table — `type: "dateTimeField"` was added to ECMA-402 for exactly this — so
 * shipping our own would be the locale blob the one-dependency rule exists to
 * refuse. A runtime that has neither the constructor nor the code falls back to
 * the unit's own name, which is English and says so.
 */
export function getUnitLabel(locale: string, type: DateSegmentType): string {
  const key = `${locale}|${type}`;
  const cached = unitLabels.get(key);
  if (cached !== undefined) return cached;
  let label: string = type;
  try {
    label = new Intl.DisplayNames(locale, { type: "dateTimeField" }).of(type) ?? type;
  } catch {
    label = type;
  }
  unitLabels.set(key, label);
  return label;
}

/**
 * The field laid out the way the locale writes it — `en-US` month first, `de-DE`
 * day first, `ja-JP` year first — with the literals between them kept, because
 * they are as much of the answer as the numbers are.
 */
export function buildSegments(parts: DateSegmentValues, context: SegmentContext): DateSegment[] {
  const shape = resolveShape(parts);
  const formatter = getDateFormatter(
    context.locale,
    formatOptionsFor(context.granularity, context.hourCycle),
  );
  return formatter.formatToParts(toUTCDateTime(shape)).map((part): DateSegment => {
    const type = asSegmentType(part.type);
    if (type === null) {
      return {
        type: "literal",
        text: part.value,
        value: null,
        min: 0,
        max: 0,
        label: "",
        isPlaceholder: false,
      };
    }
    const bounds = getSegmentBounds(type, shape, context.hourCycle);
    const filled = isSegmentFilled(parts, type);
    return {
      type,
      // Dashes as wide as the number they stand in for, so a field does not
      // change width the moment it is typed into.
      text: filled ? part.value : "-".repeat(part.value.length),
      value: filled ? getSegmentDisplay(type, shape, context.hourCycle) : null,
      min: bounds.min,
      max: bounds.max,
      label: getUnitLabel(context.locale, type),
      isPlaceholder: !filled,
    };
  });
}

/** The editable types, in display order — what the arrows and Home/End walk. */
export function editableSegments(segments: readonly DateSegment[]): DateSegmentType[] {
  const types: DateSegmentType[] = [];
  for (const segment of segments) {
    if (segment.type !== "literal") types.push(segment.type);
  }
  return types;
}

import type { RovingAction } from "../../focus/roving-focus";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Direction, InputModality } from "../../types";
import type { DateValue } from "../../utils/plain-date";

/**
 * The finest unit the field edits. It is the whole of `time-field`: the same
 * machine with `granularity: "minute"` grows an hour and a minute segment and
 * nothing else changes.
 */
export type DateGranularity = "day" | "hour" | "minute" | "second";

/** `h11`/`h24` are not offered: a 0-11 clock has no reading a spinbutton can show. */
export type DateHourCycle = "h12" | "h23";

/** The units a segment can hold. `dayPeriod` is derived from the hour, not stored. */
export type DateSegmentUnit = "year" | "month" | "day" | "hour" | "minute" | "second";

export type DateSegmentType = DateSegmentUnit | "dayPeriod";

/** What the machine holds: one number per unit, `null` while that unit is unfilled. */
export type DateSegmentValues = { readonly [K in DateSegmentUnit]: number | null };

/**
 * `DateValue` plus the time a granularity finer than a day asks for. Structurally
 * a subset of `Temporal.PlainDateTime` — same keys, same 1-based month — for the
 * same reason `DateValue` is one of `PlainDate`.
 */
export interface DateFieldValue extends DateValue {
  readonly hour?: number | undefined;
  readonly minute?: number | undefined;
  readonly second?: number | undefined;
}

/**
 * One rendered piece of the field, in display order — including the literals
 * between them, because `/` and `.` are as much a part of what a locale says as
 * the numbers are. A literal carries no value and no bounds.
 */
export interface DateSegment {
  readonly type: DateSegmentType | "literal";
  /** What to render: the formatted number, or the dashes of an unfilled unit. */
  readonly text: string;
  /** `null` while unfilled, and always `null` on a literal. */
  readonly value: number | null;
  readonly min: number;
  readonly max: number;
  /** The unit's name in the field's locale — the spinbutton's accessible name. */
  readonly label: string;
  readonly isPlaceholder: boolean;
}

export interface DateFieldValueChangeDetails {
  readonly value: DateFieldValue | null;
}

export interface DateFieldMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly value?: DateFieldValue | null | undefined;
  readonly defaultValue?: DateFieldValue | null | undefined;
  /** Compared on the date alone: a bound finer than a day is not a v1 promise. */
  readonly min?: DateValue | undefined;
  readonly max?: DateValue | undefined;
  readonly granularity?: DateGranularity | undefined;
  readonly hourCycle?: DateHourCycle | undefined;
  /**
   * The date an empty segment steps from, and the one whose month decides how
   * many days the day segment holds. Defaults to today, read once at init.
   */
  readonly placeholder?: DateFieldValue | undefined;
  /**
   * Pinned rather than read from the environment, the way `slider` and `progress`
   * pin theirs: the locale decides the *order* of the segments here, so a locale
   * resolved from the browser would have the server and the client render
   * different children and hydration would say so.
   */
  readonly locale?: string | undefined;
  readonly disabled?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly required?: boolean | undefined;
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  /**
   * The group's own accessible name, for a field standing outside a `field`. The
   * segments each name their unit and none of them names the whole, so without
   * this — and without `labelledBy` — the `role="group"` had no seam to be named
   * through at all. `labelledBy` wins where both are given, which is what the
   * accessible-name computation does anyway.
   */
  readonly label?: string | undefined;
  /**
   * Id of the element naming the group. A `div[role="group"]` is not labelable,
   * so `<label for>` cannot reach it and the field hands its own label's id here.
   */
  readonly labelledBy?: string | undefined;
  /** The intent bus engage mode pushes its scope onto. `null` disables the pad. */
  readonly intents?: IntentScopeHost | null | undefined;
  readonly onValueChange?: ((details: DateFieldValueChangeDetails) => void) | undefined;
}

export interface ResolvedDateFieldMachineProps extends DateFieldMachineProps {
  readonly granularity: DateGranularity;
  readonly hourCycle: DateHourCycle;
  readonly locale: string;
  readonly disabled: boolean;
  readonly invalid: boolean;
  readonly readOnly: boolean;
  readonly required: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface DateFieldSchema extends MachineSchema {
  state: "idle" | "focused" | "engaged";
  props: ResolvedDateFieldMachineProps;
  context: {
    /** The one source of truth. `value` is composed from it, never held beside it. */
    parts: DateSegmentValues;
    focusedSegment: DateSegmentType | null;
    /** The digits typed into the focused segment, while they are still fresh. */
    typeBuffer: string;
    focusSource: InputModality | null;
  };
  computed: {
    value: DateFieldValue | null;
    segments: DateSegment[];
    isEditable: boolean;
    isOutOfRange: boolean;
  };
  refs: {
    /** The snapshot B restores to. */
    entryParts: DateSegmentValues | null;
    /** When the last digit landed — the buffer's own clock, with no timer to leak. */
    lastDigitAt: number;
    /**
     * True for the length of a focus move the machine ordered itself. A blur that
     * arrives inside one is not the user leaving the field, and an engaged field
     * must not let go of the value because a d-pad walked to the next segment.
     */
    movingFocus: boolean;
    /**
     * The default placeholder, read from the clock the first time an arrow needs
     * one and held from then on. `null` until that happens — which is never on a
     * server, and never before a keypress on a client, so no rendered attribute
     * can depend on it.
     */
    today: DateFieldValue | null;
  };
  event:
    | { type: "SEGMENT.FOCUS"; segment: DateSegmentType }
    | { type: "SEGMENT.BLUR" }
    | { type: "SEGMENT.MOVE"; action: RovingAction }
    | { type: "SEGMENT.INPUT"; segment: DateSegmentType; digit: number }
    | { type: "SEGMENT.INCREMENT"; segment: DateSegmentType; large: boolean }
    | { type: "SEGMENT.DECREMENT"; segment: DateSegmentType; large: boolean }
    | { type: "SEGMENT.CLEAR"; segment: DateSegmentType }
    | { type: "TRIGGER.INCREMENT" }
    | { type: "TRIGGER.DECREMENT" }
    | { type: "VALUE.SET"; value: DateFieldValue | null }
    | { type: "VALUE.CLEAR" }
    | { type: "ENGAGE.START" }
    | { type: "ENGAGE.END"; committed: boolean }
    | { type: "FORM.RESET" };
  action:
    | "setValue"
    | "clearValue"
    | "setFocusedSegment"
    | "clearFocusedSegment"
    | "moveSegment"
    | "adjustSegment"
    | "adjustFocusedSegment"
    | "appendDigit"
    | "clearSegment"
    | "captureFocusSource"
    | "clearFocusSource"
    | "fillFromPlaceholder"
    | "snapshotParts"
    | "restoreParts"
    | "clearSnapshot"
    | "restoreInitialValue";
  guard: "isEditable" | "canEngage" | "isMovingFocus";
  effect: "trackModality" | "trackFormReset" | "captureSelectIntent" | "captureEngageIntents";
}

export interface DateFieldApi<T extends PropTypes = PropTypes> {
  readonly value: DateFieldValue | null;
  /** What the hidden input submits: `YYYY-MM-DD`, plus a time past `granularity: "day"`. */
  readonly valueAsString: string;
  /** In display order, literals included — the list a consumer maps over. */
  readonly segments: DateSegment[];
  readonly disabled: boolean;
  readonly invalid: boolean;
  /** A complete value outside `min`/`max`. Reported, never silently clamped. */
  readonly outOfRange: boolean;
  readonly engaged: boolean;
  readonly focusedSegment: DateSegmentType | null;
  /** The modality focus arrived under, or `null` while no segment holds it. */
  readonly focusSource: InputModality | null;
  readonly focusVisible: boolean;
  setValue(value: DateFieldValue | null): void;
  clear(): void;
  increment(): void;
  decrement(): void;
  getRootProps(): T["element"];
  getControlProps(): T["element"];
  getSegmentProps(segment: DateSegment): T["element"];
  getIncrementTriggerProps(): T["button"];
  getDecrementTriggerProps(): T["button"];
  getHiddenInputProps(): T["input"];
}

// `DateFieldMachineProps.min` and `.max` are `DateValue`, so a consumer of this barrel
// could not name the type of a bound it was passing. `calendar/index.ts` already
// re-exports it from the same module, for the same reason.
export type { DateValue } from "../../utils/plain-date";
export { anatomy, type DateFieldPart, parts } from "./date-field.anatomy";
export { connect } from "./date-field.connect";
export {
  getControlEl,
  getControlId,
  getHiddenInputEl,
  getHiddenInputId,
  getRootId,
  getSegmentEl,
  getSegmentId,
} from "./date-field.dom";
export { machine } from "./date-field.machine";
export {
  buildSegments,
  composeDateValue,
  editableSegments,
  type SegmentContext,
  toISOValue,
  toSegmentValues,
} from "./date-field.segments";
export type {
  DateFieldApi,
  DateFieldMachineProps,
  DateFieldSchema,
  DateFieldValue,
  DateFieldValueChangeDetails,
  DateGranularity,
  DateHourCycle,
  DateSegment,
  DateSegmentType,
  DateSegmentUnit,
  DateSegmentValues,
  ResolvedDateFieldMachineProps,
} from "./date-field.types";

/**
 * `<DateField/>` — the whole field: the group, the locale's own strip of
 * segments, the stepper inside it, and the mirror that submits.
 *
 * Six parts in the anatomy and four keys in `parts`, which is not an omission.
 * `segment` is not one of them because `DateFieldSegments` is what places the
 * strip and takes no props of its own: the segments are the locale's, not the
 * consumer's — `formatToParts` decides how many there are, in what order, and
 * what punctuation falls between them — so there is no single segment for a
 * `parts.segment` to reach. A consumer who needs their own markup per unit reads
 * the segments from `useDateFieldContext` and writes the parts form; that is the
 * fork this layer is the other side of. `root` is not a key either, for the
 * reason it never is: the root's props *are* this component's props.
 *
 * The stepper is always placed. It sits inside the field, it is
 * out of the tab order and hidden from a reader (`date-field.anatomy.ts`), and it
 * draws itself under `:empty` (`_date-field.scss:196`) — so it costs a reader
 * nothing and it is what the reference design shows. A field without one is a parts-form
 * shape, the same way a `<Select>` without a portal is.
 *
 * The hidden input is always placed too, and is inert until it has a name:
 * `getHiddenInputProps` writes `name: prop("name")` and a nameless control is not
 * submitted. Placing it on the `name` prop would make the composed form's markup
 * depend on a value, which is exactly what the parity table exists to keep it
 * from doing.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  DateFieldControl,
  DateFieldDecrementTrigger,
  DateFieldHiddenInput,
  DateFieldIncrementTrigger,
  DateFieldRoot,
  DateFieldSegments,
  type UseDateFieldProps,
} from "./date-field";

/** Applied last on every part, so the consumer's entry wins over the placement. */
export interface DateFieldParts {
  readonly control?: PartProps<"div"> | undefined;
  readonly incrementTrigger?: PartProps<"button"> | undefined;
  readonly decrementTrigger?: PartProps<"button"> | undefined;
  readonly hiddenInput?: PartProps<"input"> | undefined;
}

export interface DateFieldComposedProps
  extends UseDateFieldProps,
    Omit<PartProps<"div", UseDateFieldProps>, "children"> {
  readonly parts?: DateFieldParts | undefined;
}

export function DateField(props: DateFieldComposedProps): ReactNode {
  const { parts, ...root } = props;

  return (
    <DateFieldRoot {...root}>
      <DateFieldControl {...parts?.control}>
        <DateFieldSegments />
        <DateFieldIncrementTrigger {...parts?.incrementTrigger} />
        <DateFieldDecrementTrigger {...parts?.decrementTrigger} />
      </DateFieldControl>
      <DateFieldHiddenInput {...parts?.hiddenInput} />
    </DateFieldRoot>
  );
}

/**
 * The date field in React: one machine in the root, six parts that read it.
 *
 * Two things are wired here that a consumer should never wire by hand. The field
 * it sits in — inherited as machine props, never merged over the output, so a
 * field's `disabled: false` cannot talk over a control that disabled itself; and
 * the group takes the field's *control* id, which is what makes `field` notice
 * that a `div[role="group"]` is not labelable and drop its `for` rather than point
 * it at something a click cannot reach.
 *
 * The segment list is the consumer's to map over, the way the slider's markers
 * are: `useDateFieldContext().segments` is in display order, literals included, so
 * a `/` between month and day is a part like any other and nothing here has to
 * guess what a locale writes between two numbers.
 */

import * as dateField from "@standarui/core/date-field";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type DateFieldApi = dateField.DateFieldApi<ReactPropTypes>;

const DateFieldContext = createPartContext<DateFieldApi>("DateField");

export interface UseDateFieldProps extends dateField.DateFieldMachineProps, MachineRuntimeProps {}

export function useDateField(props: UseDateFieldProps): DateFieldApi {
  const host = useIntentScopeHost();

  return dateField.connect(
    useMachine(dateField.machine, {
      ...props,
      // `??` would override an explicit `null`, and `null` is how a consumer says
      // "this field answers no gamepad" while a provider is mounted above it.
      intents: props.intents === undefined ? host : props.intents,
    }),
    normalizeProps,
  );
}

/** The api of the field a subtree sits in — what a consumer maps the segments from. */
export function useDateFieldContext(): DateFieldApi {
  return DateFieldContext.usePart("DateFieldContext");
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "value",
  "defaultValue",
  "min",
  "max",
  "granularity",
  "hourCycle",
  "placeholder",
  "locale",
  "disabled",
  "invalid",
  "readOnly",
  "required",
  "name",
  "form",
  "describedBy",
  // A machine prop and not an element one: left out of this list it would not
  // merely fail to name the group, it would land on the root `div` as a bare
  // `label` attribute.
  "label",
  "labelledBy",
  "intents",
  "onValueChange",
] as const;

export interface DateFieldRootProps
  extends UseDateFieldProps,
    PartProps<"div", UseDateFieldProps> {}

export function DateFieldRoot(props: DateFieldRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();

  const api = useDateField({
    ...inheritFromField(machineProps, field),
    ids: { control: field?.controlProps.id, ...machineProps.ids },
  });

  return (
    <DateFieldContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </DateFieldContext.Provider>
  );
}

export const DateFieldControl: (props: PartProps<"div">) => ReactNode = createPart(
  DateFieldContext,
  {
    name: "DateFieldControl",
    element: "div",
    props: (api) => api.getControlProps(),
  },
);

export interface DateFieldSegmentProps extends PartProps<"div"> {
  /** One entry of `useDateFieldContext().segments`, in the order it came in. */
  readonly segment: dateField.DateSegment;
}

/**
 * Renders its own text by default: a segment's content is the formatted number,
 * or the dashes standing in for one, and having every consumer write
 * `{segment.text}` would be a chance to render the wrong segment's.
 */
export function DateFieldSegment(props: DateFieldSegmentProps): ReactNode {
  const { segment, render, asChild, children, ...elementProps } = props;
  const api = DateFieldContext.usePart("DateFieldSegment");

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getSegmentProps(segment),
    elementProps,
    children: children ?? segment.text,
  });
}

/**
 * The whole strip, in the locale's own order — what all but a handful of
 * consumers want, and the shape that keeps the keys right. A literal is keyed by
 * its rank rather than by its character, because `formatToParts` can hand back
 * the same slash twice and React would take the two for one node. Anyone who
 * needs their own markup per unit maps `useDateFieldContext().segments` instead.
 */
export function DateFieldSegments(): ReactNode {
  const api = DateFieldContext.usePart("DateFieldSegments");
  let literals = 0;

  return api.segments.map((segment) => {
    if (segment.type === "literal") literals += 1;
    return (
      <DateFieldSegment
        key={segment.type === "literal" ? `literal-${literals}` : segment.type}
        segment={segment}
      />
    );
  });
}

export const DateFieldIncrementTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  DateFieldContext,
  {
    name: "DateFieldIncrementTrigger",
    element: "button",
    props: (api) => api.getIncrementTriggerProps(),
  },
);

export const DateFieldDecrementTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  DateFieldContext,
  {
    name: "DateFieldDecrementTrigger",
    element: "button",
    props: (api) => api.getDecrementTriggerProps(),
  },
);

export const DateFieldHiddenInput: (props: PartProps<"input">) => ReactNode = createPart(
  DateFieldContext,
  {
    name: "DateFieldHiddenInput",
    element: "input",
    props: (api) => api.getHiddenInputProps(),
  },
);
